    expect(s.log.at(-1)!.systemTime).toBe(s.clock)
  })

  it('only ever moves forward, and never past the horizon', () => {
    const s = run(initialState(), { type: 'advanceClock', days: 10_000 })
    expect(s.clock).toBe(HORIZON.end)
  })

