    const s = run(initialState(),
      { type: 'advanceClock', days: 20 },
      { type: 'addFact', attr: 'salary', value: 1, validFrom: HORIZON.start },
      { type: 'undo' })
    expect(s.clock).toBeGreaterThanOrEqual(latestSystemTime(s.log))
  })
